    bronze_scabbardchape = { name = "Bronast nožnična konica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast nožnična konica za nožnice." },
    silver_scabbardchape = { name = "Srebrn nožnična konica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn nožnična konica za nožnice." },
    gilded_scabbardchape = { name = "Pozlačen nožnična konica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen nožnična konica za nožnice." },
    jewel_set_scabbardchape = { name = "Draguljast nožnična konica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast nožnična konica za nožnice." },
