    sovereign_scabbardchape_palace = { name = "Suverena scabbardchape palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ScabbardChapeMaker.ironStock = 14; ScabbardChapeMaker.bronzeStock = 12; ScabbardChapeMaker.woodStock = 12; ScabbardChapeMaker.leatherStock = 12; ScabbardChapeMaker.silverStock = 8; ScabbardChapeMaker.goldStock = 6; ScabbardChapeMaker.jewelStock = 4; ScabbardChapeMaker.pearlStock = 4
ScabbardChapeMaker.productStock = {}; ScabbardChapeMaker.buildings = {}; ScabbardChapeMaker.maker = nil; ScabbardChapeMaker.activeMaking = {}; ScabbardChapeMaker.totalProducts = 0; ScabbardChapeMaker.dayTimer = 0
function ScabbardChapeMaker.init() ScabbardChapeMaker.ironStock=14; ScabbardChapeMaker.bronzeStock=12; ScabbardChapeMaker.woodStock=12; ScabbardChapeMaker.leatherStock=12; ScabbardChapeMaker.silverStock=8; ScabbardChapeMaker.goldStock=6; ScabbardChapeMaker.jewelStock=4; ScabbardChapeMaker.pearlStock=4; ScabbardChapeMaker.productStock={}; ScabbardChapeMaker.buildings={}; ScabbardChapeMaker.maker=nil; ScabbardChapeMaker.activeMaking={}; ScabbardChapeMaker.totalProducts=0; ScabbardChapeMaker.dayTimer=0; print("[ScabbardChapeMaker] Royal Scabbard Chape Maker System initialized (6 products, 4 buildings)") end
function ScabbardChapeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ScabbardChapeMaker.maker={name=n or ("Nožničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nožničar najet: %s (spretnost: %d)",ScabbardChapeMaker.maker.name,s),"success") end; return true end
function ScabbardChapeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ScabbardChapeMaker.build(id) local ok,e=ScabbardChapeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ScabbardChapeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ScabbardChapeMaker.getQualityBonus() local b=0; for _,bd in ipairs(ScabbardChapeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ScabbardChapeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ScabbardChapeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ScabbardChapeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ScabbardChapeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ScabbardChapeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ScabbardChapeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ScabbardChapeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ScabbardChapeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ScabbardChapeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ScabbardChapeMaker.buildings==0 then return false,"Potrebna nožnična delavnica" end; if not ScabbardChapeMaker.maker then return false,"Potreben noznicar" end; return true end
function ScabbardChapeMaker.make(pt,qty) qty=qty or 1; local ok,e=ScabbardChapeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ScabbardChapeMaker.ironStock=ScabbardChapeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ScabbardChapeMaker.bronzeStock=ScabbardChapeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ScabbardChapeMaker.woodStock=ScabbardChapeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ScabbardChapeMaker.leatherStock=ScabbardChapeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ScabbardChapeMaker.silverStock=ScabbardChapeMaker.silverStock-d.silverCost*qty end; if d.goldCost then ScabbardChapeMaker.goldStock=ScabbardChapeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ScabbardChapeMaker.jewelStock=ScabbardChapeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ScabbardChapeMaker.pearlStock=ScabbardChapeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ScabbardChapeMaker.maker then t=math.max(1,t-math.floor(ScabbardChapeMaker.maker.skill/13)) end; table.insert(ScabbardChapeMaker.activeMaking,{id="scabbardchape_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ScabbardChapeMaker.completeMaking(m) local q=1.0+(ScabbardChapeMaker.getQualityBonus()/100); if ScabbardChapeMaker.maker then q=q+(ScabbardChapeMaker.maker.skill/140) end; q=math.min(2.5,q); ScabbardChapeMaker.productStock[m.productType]=(ScabbardChapeMaker.productStock[m.productType] or 0)+m.quantity; ScabbardChapeMaker.totalProducts=ScabbardChapeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ScabbardChapeMaker.maker then ScabbardChapeMaker.maker.itemsMade=ScabbardChapeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ScabbardChapeMaker.maker.skill=math.min(100,ScabbardChapeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"scabbardchape.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ScabbardChapeMaker.update(dt) if not _G.state then return end; ScabbardChapeMaker.dayTimer=ScabbardChapeMaker.dayTimer+dt; if ScabbardChapeMaker.dayTimer>=30 then ScabbardChapeMaker.dayTimer=0; for i=#ScabbardChapeMaker.activeMaking,1,-1 do local m=ScabbardChapeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ScabbardChapeMaker.completeMaking(m); table.remove(ScabbardChapeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ScabbardChapeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ScabbardChapeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ScabbardChapeMaker.getStats() return {ironStock=ScabbardChapeMaker.ironStock,bronzeStock=ScabbardChapeMaker.bronzeStock,woodStock=ScabbardChapeMaker.woodStock,leatherStock=ScabbardChapeMaker.leatherStock,silverStock=ScabbardChapeMaker.silverStock,goldStock=ScabbardChapeMaker.goldStock,jewelStock=ScabbardChapeMaker.jewelStock,pearlStock=ScabbardChapeMaker.pearlStock,productStock=ScabbardChapeMaker.productStock,numBuildings=#ScabbardChapeMaker.buildings,hasMaker=ScabbardChapeMaker.maker~=nil,makerName=ScabbardChapeMaker.maker and ScabbardChapeMaker.maker.name or "—",makerSkill=ScabbardChapeMaker.maker and ScabbardChapeMaker.maker.skill or 0,activeMaking=#ScabbardChapeMaker.activeMaking,totalProducts=ScabbardChapeMaker.totalProducts} end
return ScabbardChapeMaker
